import { HeroSection } from "@/components/shared/hero-section";
import { ComparisonTable } from "@/components/shared/comparison-table";
import { StatStrip } from "@/components/shared/stat-strip";
import { FAQAccordion } from "@/components/shared/faq-accordion";
import { CTASection } from "@/components/shared/cta-section";
import { SectionEyebrow } from "@/components/shared/section-eyebrow";
import { BRAND, FONT, SHADOW, GRADIENT, fadeUp, stagger } from "@/lib/brand";

// ─── Metadata (exported separately — file is "use client" so metadata must be
//     declared in a sibling layout or as a const. We expose it for reference.)
export const pricingMetadata: Metadata = {
  title: "Pricing — Priced like a tool, quietly fair | InkOS",
  description:
    "$29 to $199/mo. No per-booking fees. No transaction take. White-glove migration included on every plan above Solo. 14-day free trial.",
  openGraph: {
    title: "InkOS Pricing — From $29/mo",
    description:
      "$29 to $199/mo. No per-booking fees. No transaction take. White-glove migration included on every plan above Solo. 14-day free trial.",
    type: "website",
  },
  alternates: { canonical: "https://inkos.studio/pricing" },
};

// ─── Tier data ────────────────────────────────────────────────────────────────

interface PricingTierData {
  name: string;
  desc: string;
  price: string;
  period: string;
  cta: string;
  ctaHref: string;
  featured?: boolean;
  featuredLabel?: string;
  lines: string[];
}

const tiers: PricingTierData[] = [
  {
    name: "Solo",
    desc: "For one chair, one artist",
    price: "$29",
    period: "/mo",
    cta: "Start free trial",
    ctaHref: "https://inkos.up.railway.app/signup",
    lines: [
      "Today, Inbox, Calendar, Messages",
      "Unlimited bookings, deposits, consents",
      "Multi-session projects · 1 active artist",
      "Stripe Connect · standard fees",
      "Email support",
    ],
  },
  {
    name: "Studio",
    desc: "For 2–5 chairs, mixed roster",
    price: "$59",
    period: "/mo",
    cta: "Start free trial",
    ctaHref: "https://inkos.up.railway.app/signup",
    featured: true,
    featuredLabel: "Most studios",
    lines: [
      "Everything in Solo, plus:",
      "Up to 5 active artists",
      "Commission auto-splits · payroll-ready",
      "Guest residency band",
      "Free white-glove migration",
      "Chat support · 24h response",
    ],
  },
  {
    name: "Pro",
    desc: "For 6+ chairs and guest-heavy shops",
    price: "$99",
    period: "/mo",
    cta: "Start free trial",
    ctaHref: "https://inkos.up.railway.app/signup",
    lines: [
      "Everything in Studio, plus:",
      "Unlimited active artists",
      "AI design assistant · brief generator",
      "EU REACH inventory module",
      "Public guest booking pages",
      "Priority chat · 4h response",
    ],
  },
  {
    name: "Enterprise",
    desc: "For chains and franchises",
    price: "$199",
    period: "/mo per location",
    cta: "Talk to us",
    ctaHref: "/book-a-demo",
    lines: [
      "Everything in Pro, plus:",
      "Multi-location dashboard",
      "Per-location P&L, payroll, tax",
      "SSO · SCIM · audit log",
      "Dedicated migration team",
      "Dedicated account manager",
    ],
  },
];

// ─── Comparison data ──────────────────────────────────────────────────────────

const competitors = [
  { key: "daysmart", label: "DaySmart" },
  { key: "mangomint", label: "Mangomint" },
  { key: "fresha", label: "Fresha" },
  { key: "tattoogenda", label: "TattooGenda" },
  { key: "inkos", label: "InkOS", highlighted: true },
];

const comparisonRows = [
  {
    feature: "Booking + calendar",
    values: {
      daysmart: true,
      mangomint: true,
      fresha: true,
      tattoogenda: true,
      inkos: true,
    },
  },
  {
    feature: "Digital consent forms",
    values: {
      daysmart: false,
      mangomint: "Pro tier",
      fresha: false,
      tattoogenda: "Bigger plan",
      inkos: true,
    },
  },
  {
    feature: "Online deposits",
    values: {
      daysmart: true,
      mangomint: true,
      fresha: "Extra fee",
      tattoogenda: "Bigger plan",
